 "content": "def transform(grid):
    """Move all non-background cells down by one row, preserving the canvas."""
    h, w = len(grid), len(grid[0])
    background = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    out = [[background] * w for _ in range(h)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != background and r + 1 < h:
                out[r + 1][c] = value
    return out
